// Closure — counter encapsulates state
function createCounter(initial = 0) {
  let count = initial;  // Private variable
  return {
    increment: () => ++count,
    decrement: () => --count,
    getCount: () => count,
  };
}

const counter = createCounter(10);
console.log(counter.getCount());   // 10
